OPENSSL_assert(SSL_set_max_proto_version(client, TLS1_2_VERSION) == 1);
    OPENSSL_assert(SSL_set_cipher_list(client, "PSK-AES128-CBC-SHA:RSA-PSK-AES128-CBC-SHA:DHE-RSA-AES128-SHA") == 1);
    SSL_set_tlsext_host_name(client, "localhost");
    SSL_set_verify(client, SSL_VERIFY_NONE, NULL);
    SSL_set_psk_client_callback(client, psk_client_cb);
    in = BIO_new(BIO_s_mem());
    out = BIO_new(BIO_s_mem());
    SSL_set_bio(client, in, out);
    SSL_set_options(client, SSL_OP_NO_TICKET | SSL_OP_NO_RENEGOTIATION);
    SSL_set_connect_state(client);
    OPENSSL_assert((size_t)BIO_write(in, buf, len) == len);
    if (SSL_do_handshake(client) == 1) {
        /* Keep reading application data until error or EOF. */
        uint8_t tmp[1024];
        for (;;) {
            if (SSL_read(client, tmp, sizeof(tmp)) <= 0) {
                break;
            }
        }
